   Construction d'une archive en mémoire


<?php
$zip = new ZipArchive;
$zip->openString();
$zip->addFromString('hello.txt', "Hello\n");
$bytes = $zip->closeString();

var_dump(is_string($bytes), str_starts_with($bytes, "PK"));
?>


